const WAGE = 15, KWH = 0.145, MN = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];

/* ---------- crops ---------- */
const META = Object.fromEntries(D.crops_meta.map(c => [c.crop_id, c]));
const LB = {C01:.35,C02:.3125,C03:.3125,C04:.5,C05:.3125,C06:.125,C07:.75,C08:.125,C09:.75};
