const BLURB = {C01:"Soft, buttery heads grown in rafts under LED light. Our steadiest seller.",C02:"A colourful mix of baby leaves, cut young for salads.",C03:"Tender baby spinach, cut at three to four weeks.",C04:"Curly kale bunches, grown cool for a sweeter leaf.",C05:"Peppery baby arugula, a chef favourite.",C06:"Fragrant Genovese basil in small bunches. Uses a lot of light.",C07:"Sweet cherry tomatoes on the vine. Seasonal and energy-hungry.",C08:"Pea, radish and sunflower shoots, harvested in about ten days. Our best margin.",C09:"Indoor strawberries, in season April to August. The trickiest crop: lots of light, space and waste."};
const CROPS = Object.keys(LB);
const name = id => META[id].crop_name;
const short = id => ({C01:"Butterhead",C02:"Mixed greens",C07:"Cherry tomatoes"})[id] || name(id);
