const DASH = window.TC_DASHBOARD_URL || "dashboard/index.html";
const thumb = (id, cls="thumb", st="") => `<img class="${cls}" src="${img(id)}" alt="" style="${st}" loading="lazy">`;

/* ---------- store ---------- */
const KEY = "truecost_proto_v5";
function seed(){ const e=(id,crop,date,h,kwh,wn,pk,hv,ws,rs,by)=>({id,crop,date,hours:h,kwh,wn,pack:pk,harvest:hv,waste:ws,reason:rs,by,note:""});
 return { staff:[e("ST-0001","C08","2026-11-14",11.2,612,23.1,40.2,17.6,1.1,"Quality or damage","Maya R."),e("ST-0002","C09","2026-11-14",12.6,860,30.4,38.9,108.4,26.0,"Over-harvest","Maya R."),e("ST-0003","C06","2026-11-21",6.1,512,13.2,16.4,12.2,1.0,"Unsold box item","Jordan K."),e("ST-0004","C02","2026-11-21",10.2,498,19.4,42.1,57.3,5.5,"Cancelled order","Jordan K."),e("ST-0005","C01","2026-11-21",5.4,262,12.6,33.1,48.6,2.9,"Quality or damage","Maya R.")],
  customers:[{id:"CU-001",name:"Priya Shah",email:"priya@example.com",type:"Household"},{id:"CU-002",name:"Demo Bistro",email:"chef@demobistro.example",type:"Restaurant"},{id:"CU-003",name:"Marcus Lee",email:"marcus@example.com",type:"Household"},{id:"CU-004",name:"Green Fork Cafe",email:"orders@greenfork.example",type:"Restaurant"}],
  members:[{id:"MB-001",cust:"CU-001",tier:"H-ST",mode:"Delivery",start:"2026-10-03",status:"Active"},{id:"MB-002",cust:"CU-003",tier:"H-SM",mode:"Pickup",start:"2026-09-05",status:"Paused"}],
  orders:[{id:"OR-1001",cust:"CU-002",date:"2026-11-20",lines:[{crop:"C08",lb:2},{crop:"C02",lb:4}],status:3},{id:"OR-1002",cust:"CU-002",date:"2026-11-24",lines:[{crop:"C09",lb:10},{crop:"C06",lb:2}],status:1},{id:"OR-1003",cust:"CU-004",date:"2026-11-25",lines:[{crop:"C01",lb:5},{crop:"C04",lb:6},{crop:"C08",lb:1}],status:2}],
  tasks:{}, messages:[], session:{staff:null,customer:null,founder:null} }; }
let S; try { S = JSON.parse(localStorage.getItem(KEY)) || seed(); } catch(_) { S = seed(); }
const save = () => { try { localStorage.setItem(KEY, JSON.stringify(S)); } catch(_){} };
const nextId = (arr,p,w=4) => p+"-"+String(arr.reduce((m,x)=>Math.max(m,+x.id.split("-")[1]),0)+1).padStart(w,"0");

/* ---------- costing (same rates as Dataset 1) ---------- */
function entryCost(e){ const lab=e.hours*WAGE, en=e.kwh*KWH, wn=+e.wn, pk=+e.pack, prod=lab+en+wn, sell=Math.max(0,e.harvest-e.waste), wcost=e.harvest>0?prod*e.waste/e.harvest:0, total=prod+pk;
 const perLb=sell>0?total/sell:0, price=Y26.crop[e.crop].price_u/LB[e.crop], oh=Y26.crop[e.crop].overhead_u/LB[e.crop];
 return {lab,en,wn,pk,prod,sell,wcost,total,perLb,price,oh,full:perLb+oh,wp:e.harvest>0?e.waste/e.harvest:0}; }
const priceLb = id => META[id].restaurant_price_D2/LB[id];
const costLb = id => Y26.crop[id].re.tcu/LB[id];
function orderTotals(o){ const rev=o.lines.reduce((a,l)=>a+l.lb*priceLb(l.crop),0), cost=o.lines.reduce((a,l)=>a+l.lb*costLb(l.crop),0); return {rev,cost,below:o.lines.filter(l=>priceLb(l.crop)<costLb(l.crop)).map(l=>l.crop)}; }
const TIERS = {"H-SM":{label:"Small",price:26,note:"1 to 2 people",recipe:{C01:1,C02:1,C04:1,C08:1,C06:1}},"H-ST":{label:"Standard",price:35,note:"2 to 3 people",recipe:{C01:1,C02:1,C03:1,C04:1,C05:1,C08:1,C07:1,C09:1}},"H-FM":{label:"Family",price:52,note:"4 or more people",recipe:{C01:2,C02:2,C03:1,C04:2,C05:1,C08:1,C07:2,C09:2}}};
const STATUS = ["Placed","Packed","Out for delivery","Delivered"];

/* ---------- ui helpers ---------- */
let toastT;
function toast(msg, icon="circle-check"){ const l=$("#layer"); l.querySelector(".toast")?.remove(); const t=document.createElement("div"); t.className="toast"; t.setAttribute("role","status"); t.innerHTML=ic(icon)+"<span></span>"; t.querySelector("span").textContent=msg; l.append(t);
 if(G) G.from(t,{y:24,opacity:0,duration:.45,ease:"back.out(1.6)"}); clearTimeout(toastT); toastT=setTimeout(()=>{ if(G) G.to(t,{y:16,opacity:0,duration:.3,onComplete:()=>t.remove()}); else t.remove(); },3000); }
function confetti(el){ if(!G||!el) return; const r=el.getBoundingClientRect(); const cols=["#10B981","#34D399","#0067B9","#27B7EC","#F2B705","#B8E04A"];
 for(let i=0;i<14;i++){ const p=document.createElement("i"); p.style.cssText=`position:fixed;z-index:99;left:${r.left+r.width/2}px;top:${r.top+r.height/2}px;width:${6+Math.random()*5}px;height:${8+Math.random()*6}px;background:${cols[i%cols.length]};border-radius:2px;pointer-events:none`; document.body.append(p);
  G.to(p,{x:(Math.random()-.5)*320,y:-80-Math.random()*160,rotation:Math.random()*720,duration:.9,ease:"power2.out"}); G.to(p,{y:"+=220",opacity:0,duration:.8,delay:.7,ease:"power1.in",onComplete:()=>p.remove()}); } }
function countUps(root=document){ $$("[data-count]").forEach(el=>{ const to=+el.dataset.count, f=FMT[el.dataset.fmt]||FMT.int; if(!G){ el.textContent=f(to); return; } const o={v:0}; G.to(o,{v:to,duration:1.4,ease:"power3.out",scrollTrigger:window.ScrollTrigger?{trigger:el,start:"top 92%",once:true}:undefined,onUpdate:()=>el.textContent=f(o.v)}); }); }
const FMT = {int:v=>Math.round(v).toLocaleString(),money0:v=>money(v,0),pct:v=>pct(v),pct0:v=>pct(v,0),n1:v=>v.toFixed(1),tcu:v=>"$"+v.toFixed(3)};
let revIO; function reveals(){ revIO?.disconnect(); const els=$$(".reveal"); const idx=new Map(); els.forEach(el=>{ const p=el.parentElement; const n=idx.get(p)||0; el.style.setProperty("--i",Math.min(n,8)); idx.set(p,n+1); });
 if(!("IntersectionObserver" in window)){ els.forEach(e=>e.classList.add("in")); return; }
 revIO=new IntersectionObserver(es=>es.forEach(e=>{ if(e.isIntersecting){ e.target.classList.add("in"); revIO.unobserve(e.target); } }),{rootMargin:"0px 0px 40px 0px"}); els.forEach(e=>revIO.observe(e)); }
let charts=[]; const killCharts=()=>{ charts.forEach(c=>{try{c.destroy();}catch(_){}}); charts=[]; };
const AX = {chart:{fontFamily:"Inter, Arial, sans-serif",toolbar:{show:false},zoom:{enabled:false},parentHeightOffset:0,animations:{enabled:!reduce,easing:"easeinout",speed:900}},grid:{borderColor:"#EEF1F4",strokeDashArray:4},dataLabels:{enabled:false},legend:{show:false},xaxis:{axisBorder:{show:false},axisTicks:{show:false},labels:{style:{colors:"#64748B",fontSize:"12px"}}},yaxis:{labels:{style:{colors:"#64748B",fontSize:"12px"}}},tooltip:{theme:"light"}};
const merge=(a,b)=>{const o=Array.isArray(a)?[...a]:{...a};for(const k in b){o[k]=(b[k]&&typeof b[k]==="object"&&!Array.isArray(b[k])&&a&&typeof a[k]==="object"&&!Array.isArray(a[k]))?merge(a[k],b[k]):b[k];}return o;};
function chart(el,opts){ if(!el||!window.ApexCharts) return; const c=new ApexCharts(el,merge(AX,opts)); charts.push(c); c.render(); return c; }
function modal(html,{wide=false}={}){ const l=$("#layer"); l.innerHTML=`<div class="overlay" role="dialog" aria-modal="true"><div class="dialog" style="${wide?"max-width:860px":""}"><button class="close" aria-label="Close">${ic("x")}</button>${html}</div></div>`;
 const ov=l.querySelector(".overlay"), dg=l.querySelector(".dialog"); if(G){ G.from(ov,{opacity:0,duration:.25}); G.from(dg,{y:24,scale:.97,opacity:0,duration:.45,ease:"power3.out"}); }
 const close=()=>{ removeEventListener("keydown",k); if(G) G.to(ov,{opacity:0,duration:.2,onComplete:()=>l.innerHTML=""}); else l.innerHTML=""; };
 const k=e=>{ if(e.key==="Escape") close(); }; addEventListener("keydown",k); l.querySelector(".close").onclick=close; ov.onclick=e=>{ if(e.target===ov) close(); }; l.querySelectorAll("[data-close]").forEach(b=>b.onclick=close); return {close,root:l,key:k}; }
