   <div style="display:grid;gap:10px;margin-top:16px">${Object.entries(TIERS[mem.tier].recipe).map(([id,q])=>`<div class="cline">${thumb(id)}<b style="flex:1;font-size:14px">${esc(name(id))}</b><span class="small muted">${q} × ${esc(META[id].unit)}</span></div>`).join("")}</div>
